{
  "items": [
    {
      "label": "FIGURE 1.1",
      "kind": "chart",
      "title": "Poverty between 1990 and 2030 at $2.15, $3.65, and $6.85 per person per day",
      "bbox": [
        84,
        167,
        755,
        820
      ],
      "content": {
        "panels": [
          {
            "title": "a. Poverty rates",
            "y_axis": "Poverty rate (%)",
            "x_axis": "Years",
            "legend": [
              "Poverty rate at $2.15",
              "Poverty rate at $3.65",
              "Poverty rate at $6.85"
            ],
            "description": "Line chart showing poverty rates from 1990 to 2030. The $2.15 rate (red) shows a steady decline from approx. 38% in 1990 to below 10% by 2020. The $3.65 rate (yellow) declines from approx. 55% to approx. 20% by 2020. The $6.85 rate (blue) declines from approx. 70% to approx. 45% by 2020. A black horizontal dotted line is drawn at 3 percent."
          },
          {
            "title": "b. Millions of poor",
            "y_axis": "Number of poor (millions)",
            "x_axis": "Years",
            "legend": [
              "Millions of poor at $2.15",
              "Millions of poor at $3.65",
              "Millions of poor at $6.85"
            ],
            "description": "Line chart showing the number of poor in millions from 1990 to 2030. The $2.15 line (red) declines from approx. 2,000 million to under 1,000 million. The $3.65 line (yellow) shows a peak around 2000 and a decline thereafter. The $6.85 line (blue) shows a peak around 2000 and a gradual decline. A black horizontal dotted line is drawn at 256 million."
          }
        ],
        "source": "World Bank, Poverty and Inequality Platform (PIP) (version September 2024), https://pip.worldbank.org.",
        "note": "Poverty rates are reported for the $2.15, $3.65, and $6.85 per person per day poverty lines (expressed in 2017 purchasing power parity dollars). Between 2022 and 2029 poverty is projected based on per capita gross domestic product growth projections in Global Economic Prospects, June 2024 (World Bank 2024d) complemented by the Macro Poverty Outlook, Spring Meetings 2024 (World Bank 2024e) and the World Economic Outlook (IMF 2024); for 2030, average annual historic per capita growth rates (2010–19) are used. See annex 1A for more details on the projection methods. In panel a, the black horizontal dotted line is drawn at 3 percent and indicates the World Bank’s target of ending extreme poverty by 2030. In panel b, it is drawn at 256 million, which represents 3 percent of the global population projected for 2030."
      }
    }
  ]
}
